import { Component, computed, ElementRef, HostBinding, inject, input, Renderer2 } from '@angular/core';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
})
export class PctAvatar {
  private readonly el = inject(ElementRef);
  constructor() {
    const node = document.createAttribute('tabindex');
    node.value = '2';
    this.el.nativeElement.setAttributeNode(node);
  }
}
